 #include "mprisservice.h"

+#include <QDBusConnection>
+#include <QDBusObjectPath>
+#include <QDBusPendingCallWatcher>
+#include <QDBusPendingReply>
+
 #include <KActionCollection>
 #include <KGlobalAccel>
 #include <KLocalizedString>
 #include <KPluginFactory>

+#include "mpris2model.h"
+#include "mpris2sourcemodel.h"
 #include "multiplexer.h"
 #include "playercontainer.h"

 K_PLUGIN_CLASS_WITH_JSON(MprisService, "mprisservice.json")

+using namespace Qt::StringLiterals;
+
+namespace
+{
+constexpr QLatin1StringView s_login1Service("org.freedesktop.login1");
+constexpr QLatin1StringView s_login1SessionInterface("org.freedesktop.login1.Session");
+// Players often stop on their own just before the session change is reported, because their audio device goes away first
+constexpr std::chrono::seconds s_stoppedBySessionChangeWindow(2);
+}
+
 MprisService::MprisService(QObject *parent, const QList<QVariant> &)
     : KDEDModule(parent)
     , m_multiplexer(Multiplexer::self())
     , m_actionCollection(new KActionCollection(this, QStringLiteral("mediacontrol")))
+    , m_playerModel(new Mpris2Model(this))
 {
     m_activePlayer.setBinding([this] {
         return m_multiplexer->activePlayer().value();
     });

     enableGlobalShortcuts();
+
+    connect(m_playerModel, &Mpris2Model::dataChanged, this, &MprisService::onPlaybackStatusChanged);
+    watchSession();
 }

 MprisService::~MprisService() = default;
@@ -126,6 +147,84 @@ void MprisService::onVolumeDown()
     }
 }

+void MprisService::watchSession()
+{
+    QDBusMessage message = QDBusMessage::createMethodCall(s_login1Service, u"/org/freedesktop/login1"_s, u"org.freedesktop.login1.Manager"_s, u"GetSession"_s);
+    message.setArguments({u"auto"_s});
+    auto watcher = new QDBusPendingCallWatcher(QDBusConnection::systemBus().asyncCall(message), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this](QDBusPendingCallWatcher *watcher) {
+        watcher->deleteLater();
+        const QDBusPendingReply<QDBusObjectPath> reply = *watcher;
+        if (reply.isError()) {
+            return;
+        }
+        QDBusConnection::systemBus().connect(s_login1Service,
+                                             reply.value().path(),
+                                             u"org.freedesktop.DBus.Properties"_s,
+                                             u"PropertiesChanged"_s,
+                                             this,
+                                             SLOT(onSessionPropertiesChanged(QString, QVariantMap, QStringList)));
+    });
+}
+
+void MprisService::onSessionPropertiesChanged(const QString &interface, const QVariantMap &changedProperties, const QStringList &)
+{
+    if (interface != s_login1SessionInterface) {
+        return;
+    }
+    if (const auto it = changedProperties.constFind(u"Active"_s); it != changedProperties.cend()) {
+        onSessionActiveChanged(it->toBool());
+    }
+}
+
+void MprisService::onPlaybackStatusChanged(const QModelIndex &topLeft, const QModelIndex &bottomRight, const QList<int> &roles)
+{
+    if (!roles.contains(Mpris2SourceModel::PlaybackStatusRole)) {
+        return;
+    }
+    for (int row = topLeft.row(); row <= bottomRight.row(); ++row) {
+        const QModelIndex index = m_playerModel->index(row, 0);
+        if (index.data(Mpris2SourceModel::IsMultiplexerRole).toBool()) {
+            continue;
+        }
+        const auto player = index.data(Mpris2SourceModel::ContainerRole).value<PlayerContainer *>();
+        if (player && player->playbackStatus() != PlaybackStatus::Playing) {
+            m_stoppedPlaying[player->dbusAddress()] = std::chrono::steady_clock::now();
+        }
+    }
+}
+
+void MprisService::onSessionActiveChanged(bool active)
+{
+    const auto now = std::chrono::steady_clock::now();
+    if (!active) {
+        m_playersToResume.clear();
+    }
+    for (int row = 0; row < m_playerModel->rowCount(); ++row) {
+        const QModelIndex index = m_playerModel->index(row, 0);
+        if (index.data(Mpris2SourceModel::IsMultiplexerRole).toBool()) {
+            continue;
+        }
+        const auto player = index.data(Mpris2SourceModel::ContainerRole).value<PlayerContainer *>();
+        if (!player) {
+            continue;
+        }
+        if (!active) {
+            const auto stopped = m_stoppedPlaying.constFind(player->dbusAddress());
+            if (player->playbackStatus() == PlaybackStatus::Playing
+                || (stopped != m_stoppedPlaying.cend() && now - *stopped <= s_stoppedBySessionChangeWindow)) {
+                m_playersToResume.append(player->dbusAddress());
+            }
+        } else if (m_playersToResume.contains(player->dbusAddress()) && player->playbackStatus() != PlaybackStatus::Playing && player->canPlay()) {
+            player->Play();
+        }
+    }
+    if (active) {
+        m_playersToResume.clear();
+    }
+    m_stoppedPlaying.clear();
+}
+
 void MprisService::enableGlobalShortcuts()
 {
     m_actionCollection->setComponentDisplayName(i18nc("@title Name for global shortcuts category", "Media Controller"));
